import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormLabel,
  Grid,
  IconButton,
  InputAdornment,
  TextField,
  Typography,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import UploadIcon from "@mui/icons-material/Upload";
import "react-datepicker/dist/react-datepicker.css";
import { useParams } from "react-router-dom";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";

const validationSchema = yup.object().shape({
  // description: yup
  //   .string()
  //   // .trim()
  //   .required("Please enter IT Solution Additional Features Description."),
});

const DialogAdditionalFeaturesList = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess } = props;
  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");
  const [additionalFeaturesDetail, setAdditionalFeaturesDetails] = useState([]);
  const [additionalFeaturesDetailInput, setAdditionalFeaturesDetailInput] =
    useState("");
  const { id } = useParams();
  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      description: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  const handleAddAdditionalFeatureDetails = () => {
    if (additionalFeaturesDetailInput.trim()) {
      setAdditionalFeaturesDetails([
        ...additionalFeaturesDetail,
        { text: additionalFeaturesDetailInput.trim() },
      ]);
      setAdditionalFeaturesDetailInput("");
    }
  };
  const handleDeleteAddFeature = (additionalFeatureToDelete) => {
    setAdditionalFeaturesDetails(
      additionalFeaturesDetail.filter(
        (additionalFeature) => additionalFeature !== additionalFeatureToDelete
      )
    );
  };
  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(
        mode === "add"
          ? "Add Additional Features Points"
          : "Edit Additional Features"
      );

      // setAdditionalFeaturesDetails(dataToEdit?.description);
      reset({
        description: dataToEdit?.description || [],
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = () => {
    let payload = {
      descriptions: additionalFeaturesDetail,
      it_solution_feature_additional_id: id,
    };

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionAdditionalFeaturesList.edit(dataToEdit.id),
        payload
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionAdditionalFeaturesList.create,
        payload
      );
    }

    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
        setAdditionalFeaturesDetails([]);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="sub-features-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12} pb={3}>
                <FormControl fullWidth>
                  <FormLabel
                    htmlFor="key_responsibilities_points"
                    error={Boolean(errors.key_responsibilities_points)}
                  >
                    Additional Features Description
                  </FormLabel>
                  <Controller
                    name="key_responsibilities_points"
                    control={control}
                    defaultValue=""
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        type="text"
                        multiline
                        variant="standard"
                        onChange={(e) => {
                          onChange(additionalFeaturesDetail);
                          setAdditionalFeaturesDetailInput(e.target.value);
                        }}
                        id="key_responsibilities_points"
                        value={additionalFeaturesDetailInput}
                        InputProps={{
                          endAdornment: (
                            <InputAdornment position="end">
                              <IconButton
                                disableRipple
                                onClick={handleAddAdditionalFeatureDetails}
                              >
                                <Typography
                                  fontWeight={700}
                                  color={"#602de1c2"}
                                >
                                  Add
                                </Typography>
                              </IconButton>
                            </InputAdornment>
                          ),
                        }}
                      />
                    )}
                  />
                </FormControl>
              </Grid>
              {additionalFeaturesDetail.length > 0 && (
                <Grid item xs={12}>
                  <Box
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                      gap: 1,
                      border: "1px solid #ccc",
                      my: 3,
                      py: 2,
                      px: 3,
                      borderRadius: "5px",
                      width: "100%",
                    }}
                  >
                    {additionalFeaturesDetail?.map(
                      (additionalFeature, index) => (
                        <Box
                          sx={{
                            display: "flex",
                            alignItems: "end",
                            justifyContent: "space-between",
                            gap: 3,
                            flexGrow: 1,
                            wordBreak: "break-word",
                            whiteSpace: "normal",
                          }}
                          key={index}
                        >
                          <Typography
                            // label={keyWord}
                            sx={{
                              fontSize: "14px",
                            }}
                          >
                            {index + 1}. {additionalFeature.text}
                          </Typography>
                          <IconButton
                            onClick={() =>
                              handleDeleteAddFeature(additionalFeature)
                            }
                          >
                            {" "}
                            <CloseIcon
                              sx={{
                                fontSize: "16px",
                                color: "#602de1c2",
                              }}
                            />
                          </IconButton>
                        </Box>
                      )
                    )}
                  </Box>
                </Grid>
              )}
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="sub-features-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogAdditionalFeaturesList;
